import React, { useState, useEffect } from "react";
import {
  Box,
  Grid,
  Text,
  useColorModeValue,
  Center,
  Button,
  Select,
  Heading,
} from "@chakra-ui/react";
import Card from "components/card/Card.js";
import { ROS_CONFIG } from "config.js";

// Import components from Home Dashboard to keep the exact same layout
import Teleop from "views/admin/dashboards/home/components/Teleop";
import General from "views/admin/dashboards/home/components/General";

const CameraCard = (props) => {
  const { ...rest } = props;
  const textColor = useColorModeValue("secondaryGray.900", "white");
  const cardBg = useColorModeValue("white", "navy.800");

  const [robotIp, setRobotIp] = useState("10.27.174.74");
  const [topic, setTopic] = useState("/image_raw");

  useEffect(() => {
    try {
      const url = ROS_CONFIG.ROSBRIDGE_URL;
      const ip = url.split("//")[1].split(":")[0];
      if (ip) {
        setRobotIp(ip);
      }
    } catch (e) {
      console.error("Error parsing IP:", e);
    }
  }, []);

  const streamUrl = `http://${robotIp}:8080/stream?topic=${topic}`;

  return (
    <Card p="20px" bg={cardBg} {...rest}>
      <Box mb="15px">
        <Heading size="md" color={textColor} mb="2px">
          Camera Stream
        </Heading>
        <Text color="secondaryGray.600" fontSize="xs">
          Live streaming from Intel RealSense D455 on your robot.
        </Text>
      </Box>

      <Grid templateColumns="1fr 180px" gap="15px" mb="15px">
        <Box>
          <Text fontSize="xs" fontWeight="bold" color={textColor}>
            IP Address: {robotIp}:8080
          </Text>
        </Box>
        <Box>
          <Select
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            size="xs"
            borderRadius="6px"
          >
            <option value="/image_raw">/image_raw (v4l2_camera RGB)</option>
            <option value="/camera/camera/color/image_raw">/camera/camera/color/image_raw (RealSense RGB)</option>
            <option value="/camera/camera/depth/image_rect_raw">/camera/camera/depth/image_rect_raw (RealSense Depth)</option>
            <option value="/camera/color/image_raw">/camera/color/image_raw (RealSense RGB old)</option>
            <option value="/camera/depth/image_rect_raw">/camera/depth/image_rect_raw (RealSense Depth old)</option>
            <option value="/depth/image_raw">/depth/image_raw (v4l2_camera Depth)</option>
          </Select>
        </Box>
      </Grid>

      <Center
        bg="black"
        borderRadius="12px"
        overflow="hidden"
        aspectRatio={16 / 9}
        w="100%"
        h="450px"
        position="relative"
      >
        <img
          src={streamUrl}
          alt="Camera Stream Offline"
          style={{
            width: "100%",
            height: "100%",
            objectFit: "contain",
          }}
          onError={(e) => {
            e.target.style.display = "none";
            document.getElementById("camera-fallback").style.display = "flex";
          }}
          onLoad={(e) => {
            e.target.style.display = "block";
            document.getElementById("camera-fallback").style.display = "none";
          }}
        />
        <Center
          id="camera-fallback"
          position="absolute"
          top="0"
          left="0"
          right="0"
          bottom="0"
          flexDirection="column"
          color="white"
          px="20px"
          textAlign="center"
          display="flex"
        >
          <Text fontSize="md" fontWeight="bold" mb="4px">
            Camera Stream Offline
          </Text>
          <Text fontSize="xs" color="gray.400" mb="12px">
            Make sure "web_video_server" and camera node are running on the Pi.
          </Text>
          <Button
            size="xs"
            colorScheme="brand"
            onClick={() => {
              const img = document.querySelector("img");
              if (img) {
                img.src = `${streamUrl}&t=${new Date().getTime()}`;
                img.style.display = "block";
              }
              document.getElementById("camera-fallback").style.display = "none";
            }}
          >
            Retry Connection
          </Button>
        </Center>
      </Center>
    </Card>
  );
};

const CameraDashboard = () => {
  return (
    <Grid
      pt={{ base: "130px", md: "80px", xl: "80px" }}
      gridTemplateColumns={{
        base: "repeat(2, 1fr)",
        "2xl": "1fr 1.13fr 1.45fr",
      }}
      gridTemplateRows={{
        base: "repeat(2, 1fr)",
        "2xl": "1fr",
      }}
      gap={{ base: "20px", xl: "20px" }}
      display={{ base: "block", lg: "grid" }}
    >
      <CameraCard gridArea="1 / 1 / 1 / 4" />
      <Box gridArea="1 / 4 / 1 / 6">
        <General />
        <Teleop />
      </Box>
    </Grid>
  );
};

export default CameraDashboard;
